fn residual36(mut v:Bits,space:&Space)->Bits{while let Some(p)=top(&v){if let Some((b,_))=&space.piv[p]{xor(&mut v,b);}else{let mut ans=v;for q in (0..p).rev(){if (ans[q/64]>>(q%64))&1!=0{if let Some((b,_))=&space.piv[q]{xor(&mut ans,b);}}}return ans;}}v}
fn series_basis36(values:&[Series])->Space{let mut space=Space::new();for v in values{assert!(space.insert(pack(v)).1);}space.check();space}
fn kernel36(cols:&[Bits])->Vec<Bits>{let mut piv:Vec<Option<(Bits,Bits)>>=vec![None;770];let mut ker=vec![];let mut rank=0;for (i,col) in cols.iter().enumerate(){let mut v=*col;let mut co=bit(i);while let Some(p)=top(&v){if let Some((b,c))=&piv[p]{xor(&mut v,b);xor(&mut co,c);}else{piv[p]=Some((v,co));rank+=1;break;}}if top(&v).is_none(){assert_eq!(combine(&co,cols),[0;W]);ker.push(co);}}assert_eq!(rank+ker.len(),cols.len());let mut independent=Space::new();for k in &ker{assert!(independent.insert(*k).1);}independent.check();ker}
fn quotient36(label:&str,v:&[Series],target:&Space,gens:&[Series],expected:usize,table:&[[u8;32];32],out:&mut impl Write)->Vec<Series>{let mut candidate=v.to_vec();let mut products=0;for (g,gen) in gens.iter().enumerate(){let mut residuals=vec![];for c in &candidate{let value=mul(c,gen,table);assert_eq!(value,mul_independent(c,gen));products+=1;residuals.push(residual36(pack(&value),target));}if residuals.iter().any(|r|top(r).is_some()){let previous:Vec<Bits>=candidate.iter().map(pack).collect();let ker=kernel36(&residuals);writeln!(out,"step {label} {} {} {}",g+1,candidate.len(),ker.len()).unwrap();for r in &residuals{write!(out,"residual").unwrap();write_bits(out,r);}let mut next=vec![];for co in ker{let value=combine(&co,&previous);write!(out,"kernel").unwrap();write_bits(out,&co);write!(out,"candidate").unwrap();write_bits(out,&value);next.push(unpack(&value));}candidate=next;series_basis36(&candidate);println!("QUOT36_STEP label={label} generator={} dimension={}",g+1,candidate.len());}assert!(candidate.len()>=expected,"quotient below expected dimension");}
 assert_eq!(candidate.len(),expected);series_basis36(&candidate);let mut allchecks=0;for gen in gens{for c in &candidate{let value=mul(c,gen,table);assert_eq!(value,mul_independent(c,gen));assert_eq!(residual36(pack(&value),target),[0;W]);allchecks+=1;}}println!("QUOT36_QUOTIENT label={label} generators={} dimension={} construction_products={products} final_memberships={allchecks} independent_products=all",gens.len(),candidate.len());candidate}
fn read_basis36(path:&str)->Vec<Series>{let text=fs::read_to_string(path).unwrap();let mut out=vec![];for line in text.lines(){if line.starts_with("cubic "){continue;}let p:Vec<_>=line.split_whitespace().collect();assert_eq!(p.len(),157);assert_eq!(p[0].parse::<usize>().unwrap(),out.len()+1);let mut v=[0;N];for i in 0..N{v[i]=p[i+3].parse().unwrap();assert!(v[i]<32);}out.push(v);}assert_eq!(out.len(),196);out}
fn main(){let args:Vec<String>=env::args().collect();assert_eq!(args.len(),4);let spaces=read(&args[1]);let divisor=read_basis36(&args[2]);fs::create_dir(&args[3]).unwrap();let mut table=[[0u8;32];32];for a in 0..32{for b in 0..32{table[a][b]=field(a as u8,b as u8);assert_eq!(table[a][b],field_independent(a as u8,b as u8));}}
 let mut out=BufWriter::new(fs::File::create(format!("{}/quotient-certificates.txt",args[3])).unwrap());let v=&spaces[2];let vspace=series_basis36(v);let zero_complement=quotient36("zero-control",v,&vspace,&spaces[1],68,&table,&mut out);let l1=series_basis36(&spaces[0]);for c in &zero_complement{assert_eq!(residual36(pack(c),&l1),[0;W]);}
 let s=divisor[0];assert!(s.iter().any(|&x|x!=0));assert!(s[..9].iter().all(|&x|x==0));let sv:Vec<Series>=v.iter().map(|t|{let c=mul(&s,t,&table);assert_eq!(c,mul_independent(&s,t));c}).collect();let target=series_basis36(&sv);assert_eq!(target.basis.len(),324);
 let flipped=quotient36("flip",v,&target,&divisor,68,&table,&mut out);let flipped_space=series_basis36(&flipped);assert_eq!(residual36(pack(&s),&flipped_space),[0;W]);let back=quotient36("same-section-double-flip",v,&target,&flipped,196,&table,&mut out);let original=series_basis36(&divisor);for c in &back{assert_eq!(residual36(pack(c),&original),[0;W]);}
 // The target is proper in A: find and reject an actual nonmembership vector.
 let bad=(0..770).map(bit).find(|b|top(&residual36(*b,&target)).is_some()).unwrap();assert_ne!(residual36(bad,&target),[0;W]);
 for (label,basis) in [("flip",flipped),("double-flip",back)]{let mut file=BufWriter::new(fs::File::create(format!("{}/{label}-basis.txt",args[3])).unwrap());for (i,val) in basis.iter().enumerate(){write!(file,"{}",i+1).unwrap();for x in val{write!(file," {x}").unwrap();}writeln!(file).unwrap();}file.flush().unwrap();}
 out.flush().unwrap();println!("QUOT36_RESULT zero_control_dimension=68 flip_dimension=68 double_flip_dimension=196 double_flip_equals_original=true target_dimension=324 nonunit_section=true all_generator_memberships=checked corrupt_membership=rejected");println!("QUOT36_ALL_CHECKS_PASS");}
